import os
from typing import Any, Dict, Iterable, List, Optional, Sequence

from google.cloud import pubsub_v1
from google.api_core.exceptions import GoogleAPIError


def publish_batch_messages(
    project_id: str,
    topic_id: str,
    messages: Sequence[Dict[str, Any]],
    ordering_key: Optional[str] = None,
) -> List[str]:
    """
    Publish a batch of messages to Google Cloud Pub/Sub.

    Each message dict may contain:
      - data: bytes or str (required)
      - attributes: dict[str, str] (optional)
      - message_id: str (optional, used as an attribute if provided)

    Returns the list of published message IDs in the same order as input.
    """
    publisher = pubsub_v1.PublisherClient()
    topic_path = publisher.topic_path(project_id, topic_id)

    futures = []
    for msg in messages:
        data = msg.get("data")
        if data is None:
            raise ValueError("Each message must include a 'data' field.")
        if isinstance(data, str):
            data = data.encode("utf-8")
        elif not isinstance(data, (bytes, bytearray)):
            raise TypeError("'data' must be bytes or str.")

        attributes = dict(msg.get("attributes") or {})
        if "message_id" in msg and msg["message_id"] is not None:
            attributes["message_id"] = str(msg["message_id"])

        publish_kwargs = {"data": bytes(data), "attributes": attributes}
        if ordering_key:
            publish_kwargs["ordering_key"] = ordering_key

        futures.append(publisher.publish(topic_path, **publish_kwargs))

    message_ids: List[str] = []
    for future in futures:
        try:
            message_ids.append(future.result())
        except GoogleAPIError:
            raise
    return message_ids


def publish_batch_from_iterable(
    project_id: str,
    topic_id: str,
    payloads: Iterable[Any],
) -> List[str]:
    """
    Convenience wrapper that accepts an iterable of payloads and publishes them.

    Supported payload forms:
      - str / bytes: sent as message data
      - dict: forwarded to publish_batch_messages as-is
    """
    normalized: List[Dict[str, Any]] = []
    for idx, payload in enumerate(payloads):
        if isinstance(payload, dict):
            normalized.append(payload)
        elif isinstance(payload, str):
            normalized.append({"data": payload, "attributes": {"index": str(idx)}})
        elif isinstance(payload, (bytes, bytearray)):
            normalized.append({"data": bytes(payload), "attributes": {"index": str(idx)}})
        else:
            raise TypeError("payloads must contain dict, str, or bytes values.")
    return publish_batch_messages(project_id, topic_id, normalized)
